/// <summary>
/// The <t>VendPackingSlipJour</t> table extension
/// </summary>
[ExtensionOf(tableStr(VendPackingSlipJour))]
final class METVendPackingSlipJour_Extension
{
}

Method.Source:
/// <summary>
/// Disaply method to get the legal entity
/// </summary>
/// <returns>Returns the legal entity</returns>
[SysClientCacheDataMethodAttribute(true)]
public display DataAreaId displayCompany()
{
    return this.DataAreaId;
}

/// <summary>
/// Disaply method to get the product receipt line amount including GST
/// </summary>
/// <returns>Returns the product receipt line amount including GST</returns>
[SysClientCacheDataMethodAttribute(true)]
public display Amount productReceiptTotal()
{
    PurchTotals totals = PurchTotals::newPurchTable(PurchTable::find(this.PurchId), enum2int(PurchUpdate::PackingSlip));

    totals.calc(true);

    return totals.purchTotalAmount();
}

/// <summary>
/// Disaply method to get the Ledger voucher
/// </summary>
/// <returns>Returns the voucher</returns>
[SysClientCacheDataMethodAttribute(true)]
public display Voucher displayLedgerVoucher()
{
    VendPackingSlipVersion vendPackingSlipVersion;

    select firstonly LedgerVoucher from  vendPackingSlipVersion order by RecId desc
        where vendPackingSlipVersion.VendPackingSlipJour == this.RecId;

    return vendPackingSlipVersion.LedgerVoucher;
}
